<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Bounce Lab · Physics Playground</title>
<style>
  :root{
    --bg:#0a0e13; --stage1:#0e151d; --stage2:#0b1016;
    --line:#22303f; --line2:#2e4054;
    --ink:#e9f1f8; --dim:#8fa1b3; --faint:#5b6b7c;
    --amber:#ffb454; --teal:#4fd8c4; --coral:#ff6f61; --sky:#69b7ff;
    --mono:ui-monospace,"SF Mono","Cascadia Mono",Menlo,Consolas,"Liberation Mono",monospace;
    --disp:"Haettenschweiler","Impact","Arial Narrow",sans-serif;
    --body:system-ui,"Segoe UI",Helvetica,Arial,sans-serif;
  }
  *{box-sizing:border-box;margin:0;padding:0}
  html,body{min-height:100%}
  body{
    background:
      radial-gradient(1000px 520px at 10% -10%, rgba(79,216,196,.075), transparent 60%),
      radial-gradient(1100px 640px at 105% 115%, rgba(255,180,84,.07), transparent 60%),
      var(--bg);
    color:var(--ink); font-family:var(--body);
    display:flex; flex-direction:column; align-items:center;
    padding:30px 20px 42px;
  }
  body::before{
    content:""; position:fixed; inset:0; pointer-events:none; z-index:0;
    background:
      linear-gradient(rgba(146,170,196,.045) 1px, transparent 1px) 0 0/100% 34px,
      linear-gradient(90deg, rgba(146,170,196,.045) 1px, transparent 1px) 0 0/34px 100%;
    -webkit-mask-image:radial-gradient(ellipse 95% 85% at 50% 40%, #000 30%, transparent 100%);
            mask-image:radial-gradient(ellipse 95% 85% at 50% 40%, #000 30%, transparent 100%);
  }
  ::selection{background:rgba(255,180,84,.35)}
  .wrap{width:min(100%,840px); position:relative; z-index:1; display:flex; flex-direction:column; gap:16px}

  /* ---------- header ---------- */
  header{display:flex; justify-content:space-between; align-items:flex-end; gap:20px; flex-wrap:wrap}
  .tag{font:600 10.5px/1 var(--mono); letter-spacing:.32em; color:var(--amber); text-transform:uppercase}
  h1{font-family:var(--disp); font-weight:400; font-size:clamp(42px,7vw,60px); line-height:.92;
     letter-spacing:.02em; text-transform:uppercase; margin-top:8px}
  h1 .alt{color:var(--amber)}
  @supports (-webkit-text-stroke:1px #000){
    h1 .alt{color:transparent; -webkit-text-stroke:1.6px var(--amber)}
  }
  .spec{display:flex; gap:24px; font-family:var(--mono)}
  .spec div{display:flex; flex-direction:column; gap:4px; align-items:flex-end}
  .spec dt{font-size:9.5px; letter-spacing:.22em; color:var(--faint); text-transform:uppercase}
  .spec dd{font-size:12.5px; color:var(--dim)}

  /* ---------- chamber ---------- */
  .stage{
    position:relative; margin:0 auto;
    width:min(100%,780px); min-width:400px;
    height:clamp(400px,60vh,540px); min-height:400px;
    border:1px solid var(--line); border-radius:10px; overflow:hidden;
    background:
      radial-gradient(700px 300px at 50% -8%, rgba(105,183,255,.06), transparent 70%),
      radial-gradient(560px 280px at 88% 108%, rgba(255,180,84,.05), transparent 70%),
      linear-gradient(rgba(146,170,196,.05) 1px, transparent 1px) 0 0/100% 30px,
      linear-gradient(90deg, rgba(146,170,196,.05) 1px, transparent 1px) 0 0/30px 100%,
      linear-gradient(180deg,var(--stage1),var(--stage2));
    box-shadow:0 30px 60px -30px rgba(0,0,0,.75), inset 0 1px 0 rgba(255,255,255,.03);
  }
  #sim{display:block; width:100%; height:100%; cursor:crosshair; touch-action:none}
  .corner{position:absolute; width:14px; height:14px; border:2px solid var(--amber);
          opacity:.8; pointer-events:none; z-index:3; transition:opacity .2s;
          filter:drop-shadow(0 0 6px rgba(255,180,84,.45))}
  .stage:hover .corner{opacity:1}
  .c-tl{top:6px;left:6px;border-right:0;border-bottom:0}
  .c-tr{top:6px;right:6px;border-left:0;border-bottom:0}
  .c-bl{bottom:6px;left:6px;border-right:0;border-top:0}
  .c-br{bottom:6px;right:6px;border-left:0;border-top:0}
  .hud{position:absolute; top:11px; left:15px; z-index:2; display:flex; gap:9px; align-items:center;
       font:500 11px var(--mono); color:var(--dim); letter-spacing:.08em; text-transform:uppercase;
       pointer-events:none}
  .hud.br{left:auto; right:15px; top:auto; bottom:11px; color:var(--faint)}
  .dot{width:7px;height:7px;border-radius:50%;background:var(--teal);
       box-shadow:0 0 9px var(--teal); animation:pulse 1.6s ease-in-out infinite}
  .dot.paused{background:var(--amber); box-shadow:0 0 9px var(--amber); animation:none}
  @keyframes pulse{0%,100%{opacity:1}50%{opacity:.3}}

  /* ---------- control deck ---------- */
  .deck{width:min(100%,780px); margin:0 auto; display:flex; justify-content:space-between;
        align-items:center; gap:16px; flex-wrap:wrap}
  .btns{display:flex; gap:10px; flex-wrap:wrap}
  .btn{font:600 12px/1 var(--mono); letter-spacing:.14em; text-transform:uppercase;
       padding:12px 18px; background:#141c26; border:1px solid var(--line2); border-radius:8px;
       color:#dbe7f3; cursor:pointer; transition:transform .16s ease, border-color .16s, color .16s,
       background .16s, box-shadow .16s}
  .btn:hover{transform:translateY(-1px); border-color:var(--acc); color:var(--acc);
             box-shadow:0 6px 16px -8px var(--acc)}
  .btn:active{transform:translateY(1px) scale(.98)}
  .btn:focus-visible{outline:2px solid var(--sky); outline-offset:2px}
  .btn-play{--acc:var(--teal)}
  .btn-clear{--acc:var(--coral)}
  .btn-ghost{--acc:var(--sky); padding:12px 13px}
  .btn-ghost.off{color:var(--faint)}
  .btn-drop{--acc:var(--amber); background:var(--amber); border-color:var(--amber); color:#221302; font-weight:700}
  .btn-drop:hover{background:#ffc677; color:#221302; box-shadow:0 6px 18px -6px rgba(255,180,84,.55)}
  .hints{font:400 11px var(--mono); color:var(--faint); letter-spacing:.05em}
  kbd{font:600 10px var(--mono); background:#151e29; border:1px solid var(--line2);
      border-bottom-width:2px; border-radius:5px; padding:2px 6px; color:var(--dim)}
  footer{font:400 11px var(--mono); color:var(--faint); letter-spacing:.06em; text-align:center}
  footer b{color:var(--dim); font-weight:600}
  @media (prefers-reduced-motion:reduce){
    .dot{animation:none} .btn{transition:none}
  }
</style>
