<body>
<div class="wrap">

  <header>
    <div>
      <div class="tag">Experiment 01 · Rigid-Body Chamber</div>
      <h1>Bounce <span class="alt">Lab</span></h1>
    </div>
    <dl class="spec">
      <div><dt>gravity</dt><dd>0.35 px/f²</dd></div>
      <div><dt>restitution</dt><dd>0.82</dd></div>
      <div><dt>walls</dt><dd>clamp + damp</dd></div>
    </dl>
  </header>

  <div class="stage" id="stage">
    <canvas id="sim" aria-label="Physics sandbox — click to spawn balls"></canvas>
    <span class="corner c-tl"></span><span class="corner c-tr"></span>
    <span class="corner c-bl"></span><span class="corner c-br"></span>
    <div class="hud" aria-hidden="true">
      <span class="dot" id="dot"></span><span id="state">running</span>
      <span>·</span><span><span id="count">0</span> balls</span>
      <span>·</span><span><span id="fps">60</span> fps</span>
    </div>
    <div class="hud br" aria-hidden="true" id="dims">— × —</div>
  </div>

  <div class="deck">
    <div class="btns">
      <button id="drop"  class="btn btn-drop"  type="button">▼ Drop</button>
      <button id="play"  class="btn btn-play"  type="button" aria-pressed="true">❚❚ Pause</button>
      <button id="clear" class="btn btn-clear" type="button">✕ Clear</button>
      <button id="sound" class="btn btn-ghost" type="button" aria-pressed="true">snd on</button>
    </div>
    <p class="hints">click the chamber to spawn · <kbd>D</kbd> drop · <kbd>Space</kbd> play · <kbd>C</kbd> clear</p>
  </div>

  <footer>one file · <b>zero dependencies</b> · semi-implicit euler with clamped, damped wall collisions</footer>
</div>

<script>
(() => {
'use strict';
const $ = s => document.querySelector(s);
const canvas = $('#sim'), ctx = canvas.getContext('2d'), stage = $('#stage');
const dotEl=$('#dot'), stateEl=$('#state'), countEl=$('#count'), fpsEl=$('#fps'), dimsEl=$('#dims');
const dropBtn=$('#drop'), playBtn=$('#play'), clearBtn=$('#clear'), sndBtn=$('#sound');
const TAU = Math.PI*2;

/* ---------------- tuning ---------------- */
const G = 0.35;        // gravity, px per frame^2 (dt=1 baseline)
const REST = 0.82;     // wall restitution
const AIR = 0.9995;    // air drag per frame
const FLOOR_FRIC = 0.985;
const MAX_BALLS = 150, VMAX = 40;

const PALETTE = [
  {c:'#ffb454', h:'#ffe6bd', l:'#7d4a0e', rgb:[255,180, 84]},
  {c:'#ff6f61', h:'#ffc9c0', l:'#8c221a', rgb:[255,111, 97]},
  {c:'#4fd8c4', h:'#ccf6ee', l:'#0f6357', rgb:[ 79,216,196]},
  {c:'#69b7ff', h:'#d6eaff', l:'#1c5a9e', rgb:[105,183,255]},
  {c:'#c792ea', h:'#eedcfc', l:'#57348a', rgb:[199,146,234]},
  {c:'#b8e986', h:'#e9fad3', l:'#476f21', rgb:[184,233,134]},
];
const colA = (col,a)=>`rgba(${col.rgb[0]},${col.rgb[1]},${col.rgb[2]},${a})`;

/* ---------------- state ---------------- */
const balls = [], ripples = [], flashes = [];
let playing = true, soundOn = true, fps = 60, frameN = 0;

/* ---------------- public API ---------------- */
function addBall(x, y, vx = 0, vy = 0, r){
  const w = sim.w, h = sim.h;
  if (typeof r !== 'number' || !isFinite(r) || r < 3) r = 9 + Math.random()*11;
  r = Math.min(r, Math.min(w,h)/2 - 2);
  x = (typeof x === 'number' && isFinite(x)) ? x : w/2;
  y = (typeof y === 'number' && isFinite(y)) ? y : h*0.3;
  vx = (typeof vx === 'number' && isFinite(vx)) ? vx : 0;
  vy = (typeof vy === 'number' && isFinite(vy)) ? vy : 0;
  const b = {
    x: Math.min(Math.max(x, r), w - r),
    y: Math.min(Math.max(y, r), h - r),
    vx, vy, r,
    col: PALETTE[(Math.random()*PALETTE.length)|0],
    sq: 0, ax: 'y', trail: []
  };
  balls.push(b);
  if (balls.length > MAX_BALLS) balls.shift();
  ripples.push({x:b.x, y:b.y, t:0, col:b.col});
  if (ripples.length > 40) ripples.shift();
  updateCount();
  return {x:b.x, y:b.y, vx:b.vx, vy:b.vy, r:b.r};
}
function clear(){
  balls.length = 0; ripples.length = 0; flashes.length = 0;
  updateCount(); draw();
}
function step(dt = 1){ physics(dt); draw(); }

window.sim = { w: 400, h: 400, balls: () => balls.map(b => ({x:b.x, y:b.y, vx:b.vx, vy:b.vy, r:b.r})), addBall, clear, step };

/* ---------------- sizing ---------------- */
function resize(){
  const w = Math.max(1, Math.round(canvas.clientWidth));
  const h = Math.max(1, Math.round(canvas.clientHeight));
  const dpr = window.devicePixelRatio || 1;
  canvas.width = Math.round(w*dpr); canvas.height = Math.round(h*dpr);
  ctx.setTransform(dpr,0,0,dpr,0,0);
  sim.w = w; sim.h = h;
  for (const b of balls){
    b.x = Math.min(Math.max(b.x, b.r), w - b.r);
    b.y = Math.min(Math.max(b.y, b.r), h - b.r);
  }
  dimsEl.textContent = `${w} × ${h}`;
  draw();
}
if (window.ResizeObserver) new ResizeObserver(resize).observe(stage);
window.addEventListener('resize', resize);

/* ---------------- physics ---------------- */
function impact(b, side, sp){
  if (sp < 1.2) return;
  b.sq = Math.min(1, sp/14);
  b.ax = (side === 'l' || side === 'r') ? 'x' : 'y';
  if (sp > 2.4){
    let x=b.x, y=b.y, p=0;
    if (side==='l'){ x=2; p=b.y; } else if (side==='r'){ x=sim.w-2; p=b.y; }
    else if (side==='t'){ y=2; p=b.x; } else { y=sim.h-2; p=b.x; }
    ripples.push({x,y,t:0,col:b.col}); if (ripples.length>40) ripples.shift();
    flashes.push({side,p,pow:Math.min(1,sp/13),col:b.col}); if (flashes.length>14) flashes.shift();
  }
  sndBounce(b, sp);
}

function physics(dt){
  if (!(dt > 0)) return;
  const w = sim.w, h = sim.h;
  const drag = Math.pow(AIR, dt);
  for (let i=0;i<balls.length;i++){
    const b = balls[i];
    b.vy += G*dt;                       // gravity, always
    b.vx *= drag; b.vy *= drag;
    if (b.vx >  VMAX) b.vx =  VMAX; else if (b.vx < -VMAX) b.vx = -VMAX;
    if (b.vy >  VMAX) b.vy =  VMAX; else if (b.vy < -VMAX) b.vy = -VMAX;
    b.x += b.vx*dt; b.y += b.vy*dt;

    if (b.x < b.r){ b.x = b.r; if (b.vx < 0){ impact(b,'l',-b.vx); b.vx = -b.vx*REST; } }
    else if (b.x > w-b.r){ b.x = w-b.r; if (b.vx > 0){ impact(b,'r',b.vx); b.vx = -b.vx*REST; } }
    if (b.y < b.r){ b.y = b.r; if (b.vy < 0){ impact(b,'t',-b.vy); b.vy = -b.vy*REST; } }
    else if (b.y > h-b.r){
      b.y = h-b.r;
      if (b.vy > 0){
        impact(b,'b',b.vy);
        b.vy = -b.vy*REST;
        if (b.vy > -0.7) b.vy = 0;      // settle micro-bounces
        b.vx *= Math.pow(FLOOR_FRIC, dt);
      }
    }
  }
}

/* ---------------- rendering ---------------- */
function draw(){
  const w = sim.w, h = sim.h;
  ctx.clearRect(0,0,w,h);

  /* edge impact flashes */
  for (let i=flashes.length-1;i>=0;i--){
    const f = flashes[i]; f.pow *= 0.87;
    if (f.pow < 0.02){ flashes.splice(i,1); continue; }
    const L = 90 + f.pow*70, T = 22, a = f.pow*0.5;
    let g;
    ctx.globalAlpha = a;
    if (f.side==='b'){ g=ctx.createLinearGradient(0,h,0,h-T); g.addColorStop(0,colA(f.col,.9)); g.addColorStop(1,colA(f.col,0)); ctx.fillStyle=g; ctx.fillRect(f.p-L/2,h-T,L,T); }
    else if (f.side==='t'){ g=ctx.createLinearGradient(0,0,0,T); g.addColorStop(0,colA(f.col,.9)); g.addColorStop(1,colA(f.col,0)); ctx.fillStyle=g; ctx.fillRect(f.p-L/2,0,L,T); }
    else if (f.side==='l'){ g=ctx.createLinearGradient(0,0,T,0); g.addColorStop(0,colA(f.col,.9)); g.addColorStop(1,colA(f.col,0)); ctx.fillStyle=g; ctx.fillRect(0,f.p-L/2,T,L); }
    else { g=ctx.createLinearGradient(w,0,w-T,0); g.addColorStop(0,colA(f.col,.9)); g.addColorStop(1,colA(f.col,0)); ctx.fillStyle=g; ctx.fillRect(w-T,f.p-L/2,T,L); }
  }
  ctx.globalAlpha = 1;

  /* floor shadows */
  for (const b of balls){
    const dist = (h - b.r) - b.y;
    const prox = 1 - Math.min(1, Math.max(0, dist)/(h*0.9));
    if (prox > 0.02){
      ctx.globalAlpha = 0.32*prox*prox;
      ctx.fillStyle = '#04070b';
      const rx = b.r*(0.6 + 0.8*prox);
      ctx.beginPath(); ctx.ellipse(b.x, h-3, rx, Math.max(2, rx*0.22), 0, 0, TAU); ctx.fill();
    }
  }
  ctx.globalAlpha = 1;

  /* trails */
  for (const b of balls){
    const tr = b.trail;
    tr.push(b.x, b.y);
    if (tr.length > 18) tr.splice(0, tr.length - 18);
    ctx.fillStyle = b.col.c;
    for (let i=0;i<tr.length-2;i+=2){
      const k = (i/2 + 1)/(tr.length/2);
      ctx.globalAlpha = k*0.10;
      ctx.beginPath(); ctx.arc(tr[i], tr[i+1], b.r*(0.25 + 0.55*k), 0, TAU); ctx.fill();
    }
  }
  ctx.globalAlpha = 1;

  /* balls (squash & stretch) */
  for (const b of balls){
    ctx.save();
    ctx.translate(b.x, b.y);
    const s = b.sq*0.32;
    if (b.ax === 'y') ctx.scale(1+s, 1-s); else ctx.scale(1-s, 1+s);
    const g = ctx.createRadialGradient(-b.r*0.35, -b.r*0.45, b.r*0.1, 0, 0, b.r*1.02);
    g.addColorStop(0, b.col.h); g.addColorStop(0.5, b.col.c); g.addColorStop(1, b.col.l);
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.arc(0, 0, b.r, 0, TAU); ctx.fill();
    ctx.globalAlpha = 0.55; ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.ellipse(-b.r*0.36, -b.r*0.44, b.r*0.18, b.r*0.1, -0.7, 0, TAU); ctx.fill();
    ctx.restore();
    b.sq *= 0.87;
  }
  ctx.globalAlpha = 1;

  /* spawn / impact ripples */
  for (let i=ripples.length-1;i>=0;i--){
    const rp = ripples[i]; rp.t += 0.045;
    if (rp.t >= 1){ ripples.splice(i,1); continue; }
    const ease = 1 - Math.pow(1 - rp.t, 2);
    ctx.globalAlpha = (1 - rp.t)*0.5;
    ctx.strokeStyle = rp.col.c;
    ctx.lineWidth = 1.5 + (1 - rp.t)*1.5;
    ctx.beginPath(); ctx.arc(rp.x, rp.y, 6 + ease*34, 0, TAU); ctx.stroke();
  }
  ctx.globalAlpha = 1;
}

/* ---------------- sound ---------------- */
let AC = null, lastSnd = 0;
function audio(){
  if (!soundOn) return null;
  try{
    if (!AC) AC = new (window.AudioContext || window.webkitAudioContext)();
    if (AC.state === 'suspended') AC.resume();
    return AC;
  }catch(e){ return null; }
}
function blip(freq, vol, dur){
  const a = audio(); if (!a) return;
  try{
    const t = a.currentTime, o = a.createOscillator(), g = a.createGain();
    o.type = 'triangle'; o.frequency.setValueAtTime(freq, t);
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g); g.connect(a.destination); o.start(t); o.stop(t + dur + 0.03);
  }catch(e){}
}
function sndBounce(b, sp){
  const now = performance.now();
  if (now - lastSnd < 30) return;
  lastSnd = now;
  blip(Math.max(120, 640 - b.r*16 + sp*6), Math.min(0.12, sp/110), 0.09);
}
function sndPop(){ blip(340, 0.05, 0.07); setTimeout(()=>blip(520, 0.04, 0.06), 26); }
document.addEventListener('pointerdown', ()=>{ try{ audio(); }catch(e){} }, {once:true});

/* ---------------- main loop ---------------- */
let last = performance.now();
function loop(now){
  requestAnimationFrame(loop);
  const dms = now - last; last = now;
  if (dms > 0) fps += (1000/dms - fps)*0.08;
  if (playing) physics(Math.min(dms, 50)/16.6667);
  draw();
  if (++frameN % 20 === 0){ fpsEl.textContent = Math.round(fps); countEl.textContent = balls.length; }
}

/* ---------------- interaction ---------------- */
function updateCount(){ countEl.textContent = balls.length; }

function drop(){
  sim.addBall(sim.w*(0.18 + Math.random()*0.64), 26 + Math.random()*30, Math.random()*4 - 2, 0);
  sndPop();
}
function togglePlay(){
  playing = !playing;
  playBtn.setAttribute('aria-pressed', String(playing));
  playBtn.innerHTML = playing ? '❚❚&nbsp;Pause' : '▶&nbsp;Play';
  dotEl.classList.toggle('paused', !playing);
  stateEl.textContent = playing ? 'running' : 'paused';
}
function shock(x, y){
  for (const b of balls){
    const dx = b.x - x, dy = b.y - y, d = Math.hypot(dx, dy);
    if (d < 110 && d > 0.001){
      const f = (1 - d/110)*5.5;
      b.vx += dx/d*f; b.vy += dy/d*f - 0.6;
    }
  }
}

dropBtn.addEventListener('click', drop);
playBtn.addEventListener('click', togglePlay);
clearBtn.addEventListener('click', ()=>{ sim.clear(); blip(190, 0.05, 0.12); });
sndBtn.addEventListener('click', ()=>{
  soundOn = !soundOn;
  sndBtn.setAttribute('aria-pressed', String(soundOn));
  sndBtn.textContent = soundOn ? 'snd on' : 'snd off';
  sndBtn.classList.toggle('off', !soundOn);
  if (soundOn) blip(500, 0.05, 0.06);
});

canvas.addEventListener('pointerdown', e => {
  e.preventDefault();
  const rect = canvas.getBoundingClientRect();
  const x = (e.clientX - rect.left)*(sim.w/rect.width);
  const y = (e.clientY - rect.top)*(sim.h/rect.height);
  sim.addBall(x, y, Math.random()*3.2 - 1.6, 0);
  shock(x, y);
  sndPop();
});

window.addEventListener('keydown', e => {
  if (e.repeat || e.metaKey || e.ctrlKey || e.altKey) return;
  const t = e.target;
  if (t && (t.tagName === 'BUTTON' || t.tagName === 'INPUT')) return;
  if (e.code === 'Space'){ e.preventDefault(); togglePlay(); }
  else if (e.key === 'd' || e.key === 'D') drop();
  else if (e.key === 'c' || e.key === 'C') sim.clear();
});

/* ---------------- boot ---------------- */
resize();
sim.addBall(sim.w*0.28, sim.h*0.22,  2.4,  0, 15);
sim.addBall(sim.w*0.55, sim.h*0.12, -1.6,  0, 19);
sim.addBall(sim.w*0.78, sim.h*0.32,  0.8, -3, 11);
requestAnimationFrame(loop);
})();
</script>
</body>
</html>
